class Solution {
    public int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        answer[0] = 1;
        for (int i = 1; i < n; i++) {               // answer[i] = 左边所有数的乘积
            answer[i] = answer[i - 1] * nums[i - 1];
        }
        int right = 1;                              // 右边所有数的乘积
        for (int i = n - 1; i >= 0; i--) {
            answer[i] *= right;
            right *= nums[i];
        }
        return answer;
    }
}

